for(const [i,[name,muscle,equipment]] of MORE_EXERCISES.entries()){
 if(ExerciseDB.some(e=>e.name===name)) continue;
 ExerciseDB.push({id:'more-'+(i+1),name,en:'',muscle,assist:'عضلات همکار بسته به نوع اجرا',equipment,level:'مبتدی تا پیشرفته',type:'قدرتی / مهارتی',sets:3,reps:'۸ تا ۱۲',rest:75,minutes:5,desc:`${name}؛ گزینه‌ای برای تمرین ${muscle}. در نسخه‌های مشابه، زاویه، دستگاه و نوع گرفتن می‌تواند تکنیک را تغییر دهد.`,start:'پیش از اجرای این نسخه، تنظیم دستگاه یا وسیله را بررسی کن و با مقاومت سبک شروع کن.',steps:[['آماده‌سازی','وسیله را بررسی کن؛ وضعیت بدن را پایدار بگیر و دامنه بدون درد انتخاب کن.'],['اجرای کنترل‌شده','فقط در صورتی اجرا کن که روش همین نسخه را می‌دانی؛ حرکت را آهسته و بدون تاب دادن بدن انجام بده.'],['بازگشت','به شروع برگرد و مقاومت را کنترل کن؛ اگر فرم به‌هم خورد، مقاومت یا دامنه را کم کن.']],breath:'تنفس را پیوسته نگه دار؛ معمولاً در بخش سخت بازدم و هنگام بازگشت دم بگیر.',mistakes:['مقاومت بیش از توان؛ وزنه را کم کن.','حرکت ضربه‌ای یا جبران با تنه؛ سرعت را کاهش بده.','دامنه دردناک؛ در محدوده راحت حرکت کن و در صورت درد توقف کن.'],easy:'مقاومت کمتر یا نسخه ساده‌تری که تکنیک آن را بلدی.',hard:'پس از تسلط کامل، مقاومت یا تکرار را تدریجی افزایش بده.',caution:'این رکورد برای جست‌وجو و برنامه‌چینی است؛ راهنمای اختصاصی این نسخه هنوز به‌طور جداگانه راستی‌آزمایی نشده. تکنیک دقیق را از مربی واجد صلاحیت یا منبع معتبر بررسی کن.',catalogOnly:true});
}

for (const [i,row] of EXTRA_EXERCISES.entries()) {
 const [name,muscle,equipment]=row; if(ExerciseDB.some(e=>e.name===name)) continue;
 const id='lib-'+(i+1); ExerciseDB.push({id,name,en:'',muscle,assist:'عضلات همکار بسته به فرم اجرا',equipment,level:'مبتدی تا پیشرفته',type:'قدرتی',sets:3,reps:'۸ تا ۱۲',rest:75,minutes:5,desc:`${name}؛ حرکت رایج برای تمرین ${muscle}. انتخاب نوع اجرا و دامنه باید با وسیله و سطح تمرین هماهنگ باشد.`,start:'پیش از اجرا، تنظیم وسیله و وضعیت بدن را با راهنمای معتبر همان نسخه حرکت بررسی کن؛ با مقاومت سبک شروع کن.',steps:[['آماده‌سازی','وسیله را ایمن تنظیم کن و وضعیت شروع را بدون درد بگیر.'],['اجرای کنترل‌شده','حرکت را آهسته و در دامنه‌ای که می‌توانی کنترل کنی انجام بده؛ از تاب دادن بدن و ضربه زدن پرهیز کن.'],['بازگشت','به وضعیت شروع برگرد و وزنه را کنترل کن؛ تکرار بعدی را فقط با حفظ فرم انجام بده.']],breath:'معمولاً در بخش سخت حرکت بازدم و در بازگشت دم بگیر؛ نفس را طولانی حبس نکن.',mistakes:['انتخاب مقاومت بیش از توان؛ وزن یا مقاومت را کاهش بده.','شتاب و از دست دادن فرم؛ سرعت را کم کن.'],easy:'کاهش مقاومت، دامنه یا استفاده از نسخه ساده‌تر پس از اطمینان از ایمنی.',hard:'فقط پس از تسلط بر فرم، افزایش تدریجی مقاومت یا سختی.',caution:'این رکورد کاتالوگ، راهنمای کامل اختصاصی آن نسخه نیست. پیش از اجرای حرکت جدید، روش دقیق را از مربی واجد صلاحیت یا منبع معتبر همان حرکت بررسی کن؛ با درد حرکت را متوقف کن.',catalogOnly:true});
}

// Detailed, individually written guides for common movement variations. These are not shared generic templates.
const DETAILED_VARIATIONS = [
 {name:'پرس بالا سینه دمبل',en:'Incline Dumbbell Press',muscle:'بالاسینه',assist:'سه‌سر بازویی و سرشانه جلویی',equipment:'دو دمبل و نیمکت شیب‌دار',level:'مبتدی تا متوسط',desc:'پرس چندمفصلی برای تأکید بیشتر بر بخش ترقوه‌ای عضله سینه؛ زاویه زیاد نیمکت ممکن است سهم سرشانه جلویی را بیشتر کند.',start:'نیمکت را معمولاً حدود ۳۰ تا ۴۵ درجه تنظیم کن؛ پاها کامل روی زمین، سر و پشت روی پشتی و کتف‌ها کمی عقب و پایین باشند. یک قوس طبیعی و راحت در کمر کافی است؛ کمر را به زور گود نکن.',steps:[['تنظیم نیمکت و بدن','شیب نیمکت را از حدود ۳۰ درجه شروع کن. باسن و بالای پشت روی نیمکت بمانند، کف پاها محکم روی زمین و شکم کمی منقبض باشد.'],['گرفتن دمبل‌ها','دمبل‌ها را با کمک کنترل‌شده به کنار بالای سینه بیاور. مچ‌ها تقریباً بالای آرنج‌ها باشند و کف دست‌ها رو به جلو یا کمی متمایل به هم قرار بگیرند.'],['پایین آوردن','دمبل‌ها را آرام به طرف بخش بالایی سینه پایین بیاور. آرنج‌ها را معمولاً حدود ۳۰ تا ۶۰ درجه نسبت به تنه نگه دار؛ لازم نیست دقیقاً ۹۰ درجه باز شوند. فقط تا عمقی پایین برو که شانه بدون درد و کتف ثابت بماند.'],['فشار به بالا','با بازدم دمبل‌ها را رو به بالا و کمی به سمت هم فشار بده. آرنج‌ها را نزدیک بالای حرکت صاف کن، اما با ضربه قفل نکن. شانه‌ها را جلو نینداز و باسن را از نیمکت جدا نکن.'],['پایان تکرار','در بالا دمبل‌ها را به هم نکوب. مسیر حرکت را کنترل کن و برای تکرار بعدی دوباره آرام پایین بیاور.'] ],breath:'در پایین آوردن دم بگیر و هنگام فشار دادن به بالا بازدم کن. اگر وزنه سنگین است، نفس را طولانی حبس نکن.',mistakes:['شیب خیلی زیاد نیمکت؛ اگر فشار عمدتاً روی سرشانه است، شیب را کمتر کن.','باز شدن بیش از حد آرنج‌ها؛ مسیر آرنج را کمی نزدیک‌تر به تنه نگه دار.','پایین آوردن بیش از دامنه راحت؛ عمق را با کنترل شانه تنظیم کن.','بالا انداختن شانه یا جدا شدن باسن؛ وزنه را کم و تنه را ثابت کن.','مچ خم یا دمبل دور از آرنج؛ مچ را تقریباً روی آرنج نگه دار.'],easy:'دمبل سبک‌تر یا پرس دستگاه با شیب مناسب و بدون درد.',hard:'پس از تسلط بر فرم، افزایش کوچک وزنه یا تکرار؛ نه هر دو به‌صورت ناگهانی.',caution:'اگر درد تیز شانه یا سینه، بی‌حسی یا سرگیجه ایجاد شد، حرکت را متوقف کن. برای شروع سنگین، از یار تمرینی کمک بگیر.'},
 {name:'پشت بازو بالای سر دمبل',en:'Overhead Dumbbell Triceps Extension',muscle:'پشت بازو',assist:'میان‌تنه و تثبیت‌کننده‌های شانه',equipment:'یک دمبل',level:'مبتدی تا متوسط',desc:'حرکت تک‌مفصلی پشت بازو؛ وضعیت دست بالای سر، سر بلند عضله سه‌سر را در طول حرکت کشیده‌تر نگه می‌دارد.',start:'ایستاده یا نشسته روی نیمکت پشتی‌دار باش. یک دمبل را با هر دو دست از زیر صفحه بالایی بگیر و بالای سر نگه دار.',steps:[['قرارگیری','پاها به عرض لگن یا شانه، شکم منقبض و دنده‌ها روی لگن باشند. دمبل را با دو دست محکم بالای سر نگه دار؛ اگر تعادل سخت است بنشین و به پشتی تکیه بده.'],['خم کردن آرنج','با کنترل آرنج‌ها را خم کن و دمبل را پشت سر پایین ببر. بازوها نزدیک سر و رو به بالا بمانند؛ فقط ساعدها حرکت اصلی را انجام دهند.'],['انتخاب عمق','تا جایی پایین برو که شانه و آرنج بدون درد حرکت کنند و کمر قوس اضافه نگیرد. لازم نیست دمبل حتماً به گردن برسد.'],['باز کردن آرنج','با بازدم آرنج‌ها را صاف کن و دمبل را به بالای سر برگردان. بازوها را ثابت نگه دار و از پرتاب وزنه استفاده نکن.']],breath:'در پایین رفتن دم و هنگام صاف کردن آرنج‌ها بازدم کن.',mistakes:['باز شدن زیاد آرنج‌ها؛ فاصله را در حد راحت نگه دار.','گود شدن کمر؛ شکم را منقبض و دنده‌ها را پایین نگه دار یا بنشین.','انتخاب دمبل سنگین؛ با وزن سبک و کنترل کامل شروع کن.','حرکت کردن بازوها به جلو و عقب؛ دامنه را کمتر و آهسته‌تر کن.'],easy:'نشسته با تکیه‌گاه و دمبل سبک‌تر.',hard:'افزایش تدریجی مقاومت فقط وقتی تمام تکرارها کنترل‌شده‌اند.',caution:'اگر درد شانه یا آرنج داری یا نگه‌داشتن دمبل پشت سر ناامن است، حرکت را متوقف و از مربی کمک بگیر.'},
 {name:'پشت بازو بالای سر سیم‌کش طنابی',en:'Cable Rope Overhead Triceps Extension',muscle:'پشت بازو',assist:'میان‌تنه و تثبیت‌کننده‌های شانه',equipment:'دستگاه سیم‌کش و طناب',level:'متوسط',desc:'نسخه سیم‌کش حرکت پشت بازو بالای سر؛ کابل کشش پیوسته‌ای ایجاد می‌کند. این حرکت با پشت بازو سیم‌کش رو به پایین متفاوت است.',start:'قرقره را در پایین دستگاه قرار بده و طناب را وصل کن. پشت به دستگاه بایست، یک پا را جلو بگذار و طناب را از دو طرف بگیر.',steps:[['تنظیم کابل','قرقره پایین باشد و طناب سالم و محکم وصل شده باشد. پشت به دستگاه بایست و طناب را از دو سر بگیر؛ کابل از پشت بدن عبور کند.'],['وضعیت شروع','دست‌ها را بالای سر ببر؛ آرنج‌ها خم و رو به جلو باشند و بازوها نزدیک سر قرار بگیرند. یک قدم جلوتر بایست تا کابل کشش ملایم داشته باشد.'],['باز کردن آرنج','با بازدم آرنج‌ها را باز کن و دست‌ها را به جلو و بالا ببر. تنه را ثابت نگه دار و حرکت را از شانه یا کمر انجام نده.'],['بازگشت کنترل‌شده','با دم آرنج‌ها را خم کن و دست‌ها را آرام به عقب برگردان تا پشت سر کشش قابل‌کنترل حس شود. اجازه نده وزنه‌ها با ضربه به هم بخورند.']],breath:'هنگام صاف کردن آرنج‌ها بازدم و در بازگشت دم بگیر.',mistakes:['قرقره در ارتفاع نامناسب؛ برای این نسخه از قرقره پایین استفاده کن.','قوس زیاد کمر یا جلو دادن دنده‌ها؛ شکم را منقبض و حالت لانج را ثابت کن.','باز و بسته شدن شانه‌ها به‌جای آرنج؛ بازوها را تقریباً ثابت نگه دار.','وزنه سنگین و حرکت ضربه‌ای؛ مقاومت را کم کن.'],easy:'وزنه کمتر و دامنه‌ای که شانه‌ها در آن راحت‌اند.',hard:'افزایش تدریجی وزنه یا تکرار با فرم ثابت.',caution:'پیش از شروع، مسیر کابل و اتصال طناب را بررسی کن. اگر کابل به سر یا بدن برخورد می‌کند یا درد ایجاد می‌شود، توقف کن.'},
 {name:'پشت بازو بالای سر سیم‌کش تک‌دست',en:'Single-Arm Cable Overhead Triceps Extension',muscle:'پشت بازو',assist:'تثبیت‌کننده‌های شانه و میان‌تنه',equipment:'سیم‌کش و دستگیره تکی',level:'متوسط تا پیشرفته',desc:'نسخه تک‌دست برای تمرین هر بازو جداگانه؛ وزنه باید به‌قدری سبک باشد که تنه نچرخد.',start:'قرقره را پایین تنظیم کن، پشت به دستگاه بایست و دستگیره را با یک دست بگیر.',steps:[['آماده‌سازی','پشت به قرقره پایین بایست، دستگیره را بگیر و دست را بالای سر قرار بده. پاها را برای تعادل کمی باز یا یکی را جلو بگذار.'],['ثابت کردن تنه','شکم را منقبض کن و لگن و شانه‌ها را رو به جلو نگه دار؛ اجازه نده بدن به سمت کابل بچرخد.'],['باز کردن آرنج','آرنج را باز کن و دست را بالای سر به جلو ببر؛ بازوی بالایی تقریباً ثابت بماند.'],['بازگشت','آرنج را آرام خم کن و دست را پشت سر برگردان. همه تکرارها را با یک دست انجام بده و سپس سمت دیگر را تمرین کن.']],breath:'در باز کردن آرنج بازدم و در برگشت دم بگیر.',mistakes:['چرخیدن تنه؛ وزن را کم و وضعیت پاها را محکم کن.','بالا رفتن شانه به سمت گوش؛ شانه را آرام نگه دار.','تغییر دادن مسیر آرنج در هر تکرار؛ دامنه راحت و تکرارپذیر انتخاب کن.'],easy:'پشت بازو بالای سر با دمبل سبک و دو دست.',hard:'افزایش کوچک مقاومت پس از اجرای یکسان هر دو سمت.',caution:'در صورت درد شانه یا آرنج حرکت را متوقف کن؛ اختلاف قدرت دو سمت را با وزنه سنگین جبران نکن.'},
 {name:'پشت بازو سیم‌کش طنابی رو به پایین',en:'Rope Triceps Pushdown',muscle:'پشت بازو',assist:'ساعد و تثبیت‌کننده‌های شانه',equipment:'سیم‌کش و طناب',level:'مبتدی',desc:'حرکت پشت بازو رو به پایین با قرقره بالا؛ با نسخه بالای سر تفاوت دارد.',start:'طناب را به قرقره بالای دستگاه وصل کن و روبه‌روی دستگاه بایست.',steps:[['گرفتن طناب','دو سر طناب را بگیر، آرنج‌ها را کنار پهلو قرار بده و تنه را کمی به جلو متمایل کن؛ شانه‌ها پایین و آرام باشند.'],['فشار رو به پایین','با بازدم آرنج‌ها را صاف کن و طناب را تا کنار ران پایین ببر. آرنج‌ها را به جلو و عقب تاب نده.'],['بازگشت','با دم آرنج‌ها را کنترل‌شده خم کن تا دست‌ها به شروع برگردند؛ اجازه نده وزنه‌ها با ضربه بالا کشیده شوند.']],breath:'در فشار رو به پایین بازدم و هنگام برگشت دم بگیر.',mistakes:['حرکت دادن شانه و تنه برای کمک؛ وزنه را کم کن.','باز شدن آرنج‌ها از پهلو؛ آن‌ها را نزدیک تنه نگه دار.','خم شدن بیش از حد مچ؛ مچ را هم‌راستای ساعد نگه دار.'],easy:'مقاومت کمتر و دامنه کنترل‌شده.',hard:'افزایش تدریجی وزنه یا مکث کوتاه در پایین حرکت.',caution:'اتصال طناب را بررسی کن و در صورت درد آرنج یا مچ توقف کن.'},
 {name:'پرس سینه دمبل روی میز صاف',en:'Flat Dumbbell Bench Press',muscle:'سینه',assist:'سه‌سر بازویی و سرشانه جلویی',equipment:'دو دمبل و نیمکت صاف',level:'مبتدی تا متوسط',desc:'پرس افقی دمبل برای سینه؛ هر دست به‌طور مستقل کار می‌کند.',start:'روی نیمکت صاف دراز بکش، پاها را روی زمین قرار بده و کتف‌ها را کمی عقب و پایین نگه دار.',steps:[['شروع امن','با کمک کنترل‌شده دمبل‌ها را کنار سینه بالا بیاور. سر و باسن روی نیمکت و پاها محکم روی زمین باشند.'],['پایین رفتن','دمبل‌ها را آرام تا کنار سینه پایین بیاور؛ آرنج‌ها معمولاً حدود ۳۰ تا ۶۰ درجه از تنه فاصله داشته باشند.'],['فشار','با بازدم دمبل‌ها را رو به بالا فشار بده؛ مچ‌ها بالای آرنج و شانه‌ها دور از گوش بمانند.'],['بازگشت','بدون کوبیدن دمبل‌ها، کنترل‌شده پایین بیاور و دامنه بدون درد را حفظ کن.']],breath:'پایین رفتن دم و فشار به بالا بازدم.',mistakes:['آرنج‌های کاملاً باز؛ زاویه راحت‌تر انتخاب کن.','برخورد دمبل‌ها در بالا؛ حرکت را کنترل کن.','قوس افراطی کمر؛ وضعیت طبیعی و راحت را نگه دار.'],easy:'پرس دستگاه یا دمبل سبک‌تر.',hard:'افزایش تدریجی تکرار یا وزنه با فرم ثابت.',caution:'هنگام وزنه سنگین از یار تمرینی کمک بگیر و در صورت درد شانه توقف کن.'},
 {name:'پرس سینه هالتر',en:'Barbell Bench Press',muscle:'سینه',assist:'سه‌سر بازویی و سرشانه جلویی',equipment:'هالتر، نیمکت و پایه ایمن',level:'متوسط',desc:'پرس افقی هالتر؛ برای وزنه‌های سنگین به پایه ایمنی یا یار تمرینی نیاز است.',start:'روی نیمکت صاف دراز بکش، چشم‌ها زیر میله باشند و پاها روی زمین. تیغه‌های کتف را ثابت کن.',steps:[['ایمن‌سازی','ارتفاع پایه و قلاب ایمنی را تنظیم کن؛ اگر تنها هستی بدون پایه ایمنی مناسب سراغ وزنه سنگین نرو.'],['گرفتن میله','میله را کمی بازتر از عرض شانه بگیر، مچ را صاف نگه دار و میله را از پایه بیرون بیاور.'],['پایین آوردن','با دم میله را کنترل‌شده به بخش میانی تا پایینی سینه نزدیک کن؛ آرنج‌ها را بیش از حد باز نکن.'],['پرس','با بازدم میله را به بالا و کمی به سمت پایه حرکت بده؛ باسن روی نیمکت بماند.'],['بازگرداندن','پس از پایان تکرار، میله را با کنترل روی قلاب‌ها قرار بده و مطمئن شو دو طرف ثابت‌اند.']],breath:'دم هنگام پایین رفتن و بازدم هنگام فشار؛ برای وزنه‌های سنگین از تکنیک تنفسی فقط در صورت آموزش مناسب استفاده کن.',mistakes:['نبود یار یا پایه ایمنی؛ قبل از ست شرایط را آماده کن.','جهش میله از سینه؛ پایین رفتن آرام و بدون ضربه.','مچ خمیده؛ میله روی کف دست و مچ در امتداد ساعد باشد.'],easy:'پرس دمبل سبک یا دستگاه سینه.',hard:'افزایش تدریجی بار با تکنیک و ایمنی مناسب.',caution:'پرس هالتر سنگین را تنها و بدون قلاب ایمنی انجام نده. درد یا بی‌حسی علامت توقف است.'}
];
